class KthSmallest {
  constructor(k) {
    this.k = k;
    this.L = new MaxHeap(); // holds k smallest
    this.R = new MinHeap(); // holds the rest
  }
  insertBatch(arr) {
    for (const x of arr) this.R.push(x);
    while (this.L.size() < this.k && !this.R.empty()) this.L.push(this.R.pop());
    while (!this.R.empty() && this.L.top > this.R.top) {
      const a = this.L.pop();
      const b = this.R.pop();
      this.L.push(b);
      this.R.push(a);
    }
  }
  kth() { return this.L.top; }
}
```

